{"replacement":"
    reveal aLength;
    reveal aInvariant;
    reveal sInvariant;
    assert a.Length <= 1;
    assert oldASeq == a[..];
    assert oldS == s;
    if |oldASeq| == 0 {
      assert Model.Shuffle(oldASeq)(oldS) == Monad.Return(oldASeq)(oldS);
      assert Monad.Return(oldASeq)(oldS) == Monad.Result(oldASeq, oldS);
      assert oldASeq == a[..];
      assert oldS == s;
    } else {
      assert |oldASeq| == 1;
      assert Model.Shuffle(oldASeq)(oldS) == Model.ShuffleCurried(oldASeq, oldS, 0);
      assert |oldASeq| - 0 == 1;
      assert !(|oldASeq| - 0 > 1);
      assert Model.ShuffleCurried(oldASeq, oldS, 0) == Monad.Return(oldASeq)(oldS);
      assert Monad.Return(oldASeq)(oldS) == Monad.Result(oldASeq, oldS);
      assert oldASeq == a[..];
      assert oldS == s;
    }
  "}

